void AFoundrylinePlayerController::OpenOperations(int32 Screen){
 if(!IsLocalController())return;if(FactoryMachine)OpenFactoryComputer(0);if(Screen&&!FactoryPlant())return;if(Screen==1&&IsWalking()&&!IsNearOfficeComputer()){OperationsStatus=TEXT("Use the office computer to open the business desktop");return;}OperationsDocumentTab=0;OperationsWorkspaceTab=0;OperationsEmployeeChoice=0;OperationsJobPage=0;OperationsScreen=Screen;OperationsPage=Screen==2?2:9;OperationsListPage=0;OperationsStatus.Reset();OperationsPallets.Reset();
 if(Screen){if(auto* Camera=Cast<AFoundrylineCameraPawn>(GetPawn()))Camera->ClearCameraInput();FlushPressedKeys();bFactoryMenu=false;BuildTool=NAME_None;bDraggingBuild=false;if(!bOperationsLocked){SetIgnoreLookInput(true);SetIgnoreMoveInput(true);bOperationsLocked=true;}FInputModeGameAndUI Mode;Mode.SetHideCursorDuringCapture(false);SetInputMode(Mode);bShowMouseCursor=true;}else{if(bOperationsLocked){SetIgnoreLookInput(false);SetIgnoreMoveInput(false);bOperationsLocked=false;}ApplyViewInputMode();}
}
bool AFoundrylinePlayerController::HandleOperationsInput(const FInputKeyEventArgs& P){
 if(!IsLocalController())return false;if(OperationsScreen){if(!FactoryPlant()){OpenOperations(0);return true;}if(P.Event==IE_Pressed&&(P.Key==EKeys::Escape||P.Key==EKeys::E)){OpenOperations(0);return true;}if(P.Key==EKeys::LeftMouseButton){Super::InputKey(P);return true;}if(P.Key==EKeys::MouseScrollDown||P.Key==EKeys::MouseScrollUp){if(OperationsPage==7&&OperationsEmployeeChoice&&OperationsWorkspaceTab==0)OperationsJobPage=FMath::Max(0,OperationsJobPage+(P.Key==EKeys::MouseScrollDown?1:-1));else OperationsListPage=FMath::Max(0,OperationsListPage+(P.Key==EKeys::MouseScrollDown?1:-1));return true;}return true;}
 auto* Plant=FactoryPlant();if(!Plant||!Plant->Snapshot.Commerce.Enabled)return false;
 const bool Use=P.Event==IE_Pressed&&P.Key==EKeys::E&&IsWalking()&&!FocusedDoor();const bool Click=P.Event==IE_Pressed&&P.Key==EKeys::LeftMouseButton&&!IsWalking()&&BuildTool.IsNone()&&FactoryTool.IsNone()&&!IsOverBuildHUD();if(!Use&&!Click)return false;
 AFoundrylineOperationsTerminal* Terminal=nullptr;
 if(Click){FHitResult Hit;if(GetHitResultUnderCursor(ECC_Visibility,true,Hit))Terminal=Cast<AFoundrylineOperationsTerminal>(Hit.GetActor());}else if(PlayerCameraManager){const auto Eye=PlayerCameraManager->GetCameraLocation(),Forward=PlayerCameraManager->GetCameraRotation().Vector();float Best=270;for(TActorIterator<AFoundrylineOperationsTerminal> It(GetWorld());It;++It){const auto D=It->InteractionPoint()-Eye;if(D.Size()<Best&&D.GetSafeNormal().Dot(Forward)>.25){Best=D.Size();Terminal=*It;}}}
 if(Terminal){if(Terminal->PlantId!=Plant->BusinessPlantId)return true;OpenOperations(Terminal->Terminal);return true;}
 if(Use&&FocusedComputer())return false;
 FVector Point;if(Use)Point=PlayerCameraManager->GetCameraLocation();else{FIntVector Anchor;if(!GetCursorAnchor(Anchor))return false;Point=FVector(Anchor);}
 int Id=0;float Best=Use?80:90;for(const auto& Pallet:Plant->Snapshot.Pallets){if(Pallet.Place==EFoundrylinePalletPlace::InTransit||Pallet.Place==EFoundrylinePalletPlace::Forks)continue;const FVector At=Plant->GetActorTransform().TransformPosition(Pallet.Position);float D=FVector::Dist2D(Point,At);if(Use){const FVector Delta=At+FVector(0,0,35)-Point;const float Distance=Delta.Size(),Alignment=Delta.GetSafeNormal().Dot(PlayerCameraManager->GetCameraRotation().Vector());if(Distance>600||Alignment<.94f)continue;D=(1-Alignment)*1000+Distance*.01f;FHitResult Block;FCollisionQueryParams Query;Query.AddIgnoredActor(GetPawn());if(GetWorld()->LineTraceSingleByChannel(Block,Point,At+FVector(0,0,35),ECC_Visibility,Query)&&Block.GetActor()!=Plant&&Block.Distance+50<Distance)continue;}if(D<Best){Best=D;Id=Pallet.Id;}}if(Id){OperationsInspect=Id;OpenOperations(3);return true;}return false;
}
void AFoundrylinePlayerController::SendOperations(FFoundrylineCommerceCommand C){if(bOperationsPending)return;auto* P=FactoryPlant();if(!P)return;C.PlantId=P->BusinessPlantId;bOperationsPending=true;OperationsStatus.Reset();ServerOperationsCommand(C,++OperationsSequence);}
void AFoundrylinePlayerController::ServerOperationsCommand_Implementation(const FFoundrylineCommerceCommand& C,uint32 Seq){if(Seq<=LastOperationsSequence)return;LastOperationsSequence=Seq;const double Now=GetWorld()->GetTimeSeconds();if(Now-OperationsRateStart>1){OperationsRateStart=Now;OperationsRate=0;}FString E;bool Ok=false;if(++OperationsRate<=20){if(auto* Plant=FactoryPlant())Ok=Plant->ExecuteCommerce(this,C,E);}else E=TEXT("Please wait before sending more requests");ClientOperationsResult(Seq,Ok,E.IsEmpty()&&!Ok?TEXT("Operations unavailable"):E);}
void AFoundrylinePlayerController::ClientOperationsResult_Implementation(uint32 Seq,bool Ok,const FString& E){if(Seq!=OperationsSequence)return;bOperationsPending=false;OperationsStatus=Ok?FString():E;if(Ok)OperationsPallets.Reset();}
void AFoundrylinePlayerController::OperationsAction(FName Action){const auto S=Action.ToString();auto* P=FactoryPlant();if(S==TEXT("Close")){OpenOperations(0);return;}if(!P)return;const auto& C=P->Snapshot.Commerce;
 if(S.StartsWith(TEXT("Sort"))){const int Column=FMath::Clamp(FCString::Atoi(*S.RightChop(4)),0,4);if(OperationsSort==Column)bOperationsSortDescending=!bOperationsSortDescending;else{OperationsSort=Column;bOperationsSortDescending=false;}OperationsListPage=0;return;}
 if(S.StartsWith(TEXT("DocTab"))){OperationsDocumentTab=FMath::Clamp(FCString::Atoi(*S.RightChop(6)),0,2);return;}
 if(S.StartsWith(TEXT("Workspace"))){OperationsWorkspaceTab=FMath::Clamp(FCString::Atoi(*S.RightChop(9)),0,OperationsPage==7?2:1);OperationsListPage=0;OperationsEmployeeChoice=0;OperationsJobPage=0;if(OperationsWorkspaceTab==1&&OperationsPage==3){const auto* B=C.Bookings.FindByPredicate([&](const auto& V){return V.Inbound&&V.Id==OperationsBooking;});if(!B){B=C.Bookings.FindByPredicate([](const auto& V){return V.Inbound;});OperationsBooking=B?B->Id:0;}}if(OperationsWorkspaceTab==1&&OperationsPage==5){const auto* O=C.Orders.FindByPredicate([&](const auto& V){return V.Id==OperationsOrder&&V.Status!=EFoundrylineOrderState::Offered;});if(!O){O=C.Orders.FindByPredicate([](const auto& V){return V.Status!=EFoundrylineOrderState::Offered;});OperationsOrder=O?O->Id:0;}}return;}
 if(S.StartsWith(TEXT("CalendarBooking"))){const int Id=FCString::Atoi(*S.RightChop(15));if(C.Bookings.ContainsByPredicate([&](const auto& B){return B.Id==Id;})){OperationsPage=4;OperationsBooking=Id;OperationsDocumentTab=0;OperationsListPage=0;}return;}
 if(S.StartsWith(TEXT("LinkedOrder"))){const int Id=FCString::Atoi(*S.RightChop(11));if(C.Orders.ContainsByPredicate([&](const auto& O){return O.Id==Id;})){OperationsPage=2;OperationsOrder=Id;OperationsDocumentTab=1;OperationsListPage=0;}return;}
 if(S==TEXT("PropertyView")){EnterPropertyView();return;}if(S==TEXT("ReturnOffice")){if(bPropertyViewAccess&&!IsWalking())ToggleWalk();return;}
 if(S==TEXT("Office")){OpenOperations(1);return;}if(S==TEXT("Tablet")){OpenOperations(2);return;}if(S.StartsWith(TEXT("Page"))){OperationsPage=FMath::Clamp(FCString::Atoi(*S.RightChop(4)),0,11);OperationsListPage=0;OperationsDocumentTab=0;OperationsWorkspaceTab=0;OperationsEmployeeChoice=0;OperationsJobPage=0;if(OperationsPage<=2){auto InView=[&](const FFoundrylineCustomerOrder& O){return OperationsPage==2?O.Status!=EFoundrylineOrderState::Offered:O.Status==EFoundrylineOrderState::Offered&&O.Email==(OperationsPage==1);};const auto* Current=C.Orders.FindByPredicate([&](const auto& O){return O.Id==OperationsOrder&&InView(O);});if(!Current){const auto* First=C.Orders.FindByPredicate(InView);OperationsOrder=First?First->Id:0;}}return;}if(S.StartsWith(TEXT("Order"))){OperationsOrder=FCString::Atoi(*S.RightChop(5));OperationsDocumentTab=0;return;}if(S.StartsWith(TEXT("Booking"))){OperationsBooking=FCString::Atoi(*S.RightChop(7));OperationsDocumentTab=0;return;}
 if(S==TEXT("Previous")||S==TEXT("Next")){OperationsListPage=FMath::Max(0,OperationsListPage+(S==TEXT("Next")?1:-1));return;}
 if(S==TEXT("SheetsPlus")||S==TEXT("SheetsMinus")){OperationsSheets=FMath::Clamp(OperationsSheets+(S.EndsWith(TEXT("Plus"))?1:-1),1,10);return;}
 if(S==TEXT("TimePlus")||S==TEXT("TimeMinus")||S==TEXT("NextDay")){OperationsDelay=FMath::Clamp(OperationsDelay+(S==TEXT("NextDay")?1440:S==TEXT("TimePlus")?30:-30),30.,4320.);return;}
 if(S.StartsWith(TEXT("Carrier"))){OperationsCarrier=FMath::Clamp(FCString::Atoi(*S.RightChop(7)),0,3);OperationsDelay=FMath::Max(OperationsDelay,FFoundrylineCommerceCatalog::Carrier(OperationsCarrier).LeadMinutes+10);OperationsPallets.Reset();return;}
 if(S.StartsWith(TEXT("Pallet"))){const int Id=FCString::Atoi(*S.RightChop(6));if(OperationsPallets.Remove(Id))return;const auto* Pallet=P->Snapshot.Pallets.FindByPredicate([&](const auto& V){return V.Id==Id&&V.Place==EFoundrylinePalletPlace::Pickup&&!V.BookingId;});if(!Pallet)return;int Slots=FFoundrylineCommerceCatalog::PalletSpaces(uint8(Pallet->Part));double Weight=FFoundrylineCommerceCatalog::PalletWeight(uint8(Pallet->Part),Pallet->Quantity,Pallet->UnitLb);for(const auto& V:OperationsPallets)if(const auto* Stock=P->Snapshot.Pallets.FindByPredicate([&](const auto& X){return X.Id==V.Key;})){Slots+=FFoundrylineCommerceCatalog::PalletSpaces(uint8(Stock->Part));Weight+=FFoundrylineCommerceCatalog::PalletWeight(uint8(Stock->Part),V.Value,Stock->UnitLb);}const auto Spec=FFoundrylineCommerceCatalog::Carrier(OperationsCarrier);if(Slots>Spec.Spaces||Weight>Spec.PayloadLb){OperationsStatus=TEXT("This vehicle is full. Choose a larger vehicle or fewer pallets.");return;}OperationsPallets.Add(Id,Pallet->Quantity);return;}
 if(S==TEXT("Speed1")||S==TEXT("Speed4")||S==TEXT("Speed8")){FactoryAction(FName(*S));return;}
 if(S==TEXT("ProgramOrder")){const auto* Order=C.Orders.FindByPredicate([&](const auto& O){return O.Id==OperationsOrder&&O.Status==EFoundrylineOrderState::Accepted;});if(!Order)Order=C.Orders.FindByPredicate([](const auto& O){return O.Status==EFoundrylineOrderState::Accepted;});if(!Order)return;const auto Programs=P->Snapshot.Programs.FilterByPredicate([](const auto& V){return V.Machine==1;});const int Index=Programs.IndexOfByPredicate([&](const auto& V){return int(V.Part)==Order->Part;});if(Index==INDEX_NONE)return;int Available=0;for(const auto& Pallet:P->Snapshot.Pallets)if(int(Pallet.Part)==Order->Part&&!Pallet.BookingId)Available+=Pallet.Quantity;const int Needed=Order->Quantity-Order->Delivered-Available;if(Needed<=0){OpenOperations(2);OperationsPage=8;return;}const int Quantity=FMath::Clamp(Needed,1,200);OpenOperations(0);OpenFactoryComputer(1);FactoryProgramIndex=Index;FactoryBatch=Quantity;bFactoryAuto=false;return;}
 if(S==TEXT("Run")){FactoryAction(TEXT("Run"));return;}if(S==TEXT("Plasma")){OpenOperations(0);OpenFactoryComputer(1);return;}if(S==TEXT("BrakeComputer")){OpenOperations(0);OpenFactoryComputer(2);return;}
 if(S.StartsWith(TEXT("SelectEmployee"))){const FString Value=S.RightChop(14);if(!Value.IsNumeric())return;const int Id=FCString::Atoi(*Value);const auto Roster=FFoundrylineEmployeeRoster::Build(P->Snapshot);const auto* Employee=Roster.FindByPredicate([&](const auto& E){return E.Id==Id&&E.CompanyId==P->BusinessCompanyId&&E.PlantId==P->BusinessPlantId;});if(!Employee)return;OperationsEmployeeChoice=Id;OperationsJobRole=int(Employee->Role)<=2?int(Employee->Role):0;OperationsJobPage=0;OperationsWorkspaceTab=0;OperationsStatus.Reset();return;}
 if(S==TEXT("TeamRoster")){OperationsEmployeeChoice=0;OperationsJobPage=0;return;}
 if(S.StartsWith(TEXT("JobRole"))){const FString Value=S.RightChop(7);if(!Value.IsNumeric())return;const int Choice=FCString::Atoi(*Value);if(Choice<0||Choice>2)return;OperationsJobRole=Choice;OperationsJobPage=0;return;}
 if(S==TEXT("JobNext")||S==TEXT("JobPrevious")){OperationsJobPage=FMath::Max(0,OperationsJobPage+(S==TEXT("JobNext")?1:-1));return;}
 if(S==TEXT("HirePerson")||S.StartsWith(TEXT("Hire"))){if(S!=TEXT("HirePerson")){const auto Value=S.RightChop(4);if(!Value.IsNumeric()||FCString::Atoi(*Value)<0||FCString::Atoi(*Value)>3)return;}if(OperationsHireRequest.IsValid()&&!P->Snapshot.HireRequests.Contains(OperationsHireRequest))return;FFoundrylineFactoryCommand Command;Command.Action=EFoundrylineFactoryAction::HireEmployee;Command.Count=3;Command.RequestId=OperationsHireRequest=FGuid::NewGuid();Command.TargetPlantId=P->BusinessPlantId;OperationsStatus.Reset();SendFactory(Command);return;}
 if(S.StartsWith(TEXT("AssignEmployee"))){TArray<FString> V;S.RightChop(14).ParseIntoArray(V,TEXT("_"));if(V.Num()!=3||!V[0].IsNumeric()||!V[1].IsNumeric()||!V[2].IsNumeric())return;const int Id=FCString::Atoi(*V[0]),EmployeeRole=FCString::Atoi(*V[1]),Target=FCString::Atoi(*V[2]);if(Id<=0||EmployeeRole<0||EmployeeRole>3||Target<0||(EmployeeRole==3&&Target!=0))return;FFoundrylineFactoryCommand Command;Command.Action=EFoundrylineFactoryAction::AssignEmployee;Command.Id=Id;Command.Count=EmployeeRole;Command.Other=Target;Command.TargetPlantId=P->BusinessPlantId;OperationsStatus.Reset();SendFactory(Command);return;}
 FFoundrylineCommerceCommand Cmd;if(S==TEXT("Accept")){Cmd.Action=EFoundrylineCommerceAction::AcceptOrder;Cmd.Id=OperationsOrder;}else if(S==TEXT("Assign")){Cmd.Action=EFoundrylineCommerceAction::AssignPickup;Cmd.Id=OperationsOrder;}else if(S==TEXT("BuySteel")){Cmd.Action=EFoundrylineCommerceAction::BuySteel;Cmd.Quantity=OperationsSheets;Cmd.Arrival=C.Clock+OperationsDelay;}else if(S==TEXT("Book")){Cmd.Action=EFoundrylineCommerceAction::BookPickup;Cmd.Choice=OperationsCarrier;Cmd.Arrival=C.Clock+OperationsDelay;for(const auto& Pair:OperationsPallets){Cmd.Pallets.Add(Pair.Key);Cmd.Quantities.Add(Pair.Value);}}else if(S==TEXT("Rebook")){Cmd.Action=EFoundrylineCommerceAction::Reschedule;Cmd.Id=OperationsBooking;Cmd.Arrival=C.Clock+OperationsDelay;}else if(S==TEXT("BuyBrake")){Cmd.Action=EFoundrylineCommerceAction::BuyBrake;}else if(S==TEXT("BuyForklift")){Cmd.Action=EFoundrylineCommerceAction::BuyForklift;}else if(S.StartsWith(TEXT("Priority"))){TArray<FString> Values;S.RightChop(8).ParseIntoArray(Values,TEXT("_"));if(Values.Num()!=2)return;const int Id=FCString::Atoi(*Values[0]),Task=FCString::Atoi(*Values[1]);const auto* D=P->Snapshot.Drivers.FindByPredicate([&](const auto& V){return V.Id==Id;});if(!D||Task<0||Task>2)return;Cmd.Action=EFoundrylineCommerceAction::DriverPriority;Cmd.Id=Id;Cmd.Choice=Task;Cmd.Quantity=(D->Priorities[Task]+1)%3;}else return;SendOperations(Cmd);
}


bool AFoundrylinePlayerController::IsNearOfficeComputer()const{if(!IsWalking()||!GetPawn())return false;const auto* Plant=FactoryPlant();if(!Plant)return false;for(TActorIterator<AFoundrylineOperationsTerminal> It(GetWorld());It;++It)if(It->Terminal==1&&It->PlantId==Plant->BusinessPlantId&&FVector::Dist(GetPawn()->GetActorLocation(),It->InteractionPoint())<270)return true;return false;}
void AFoundrylinePlayerController::EnterPropertyView(){if(!IsLocalController()||OperationsScreen!=1)return;if(HasAuthority())ServerEnterPropertyView_Implementation();else ServerEnterPropertyView();}
void AFoundrylinePlayerController::ServerEnterPropertyView_Implementation(){if(!IsNearOfficeComputer()||LocalFreightRig||LocalMaterialCell)return;OfficeReturn=GetPawn()->GetActorTransform();OfficeReturn.SetRotation(FQuat(GetControlRotation()));bHasOfficeReturn=true;bTopDownRoofsVisible=false;PropertyViewPlant=FactoryPlant()->BusinessPlantId;bPropertyViewAccess=true;ServerToggleWalk_Implementation();if(!IsWalking()){GetWorldTimerManager().SetTimer(PropertyViewTimer,this,&AFoundrylinePlayerController::ValidatePropertyView,.5f,true);ClientPropertyViewMode(true);}else bPropertyViewAccess=false;}
void AFoundrylinePlayerController::ClientPropertyViewMode_Implementation(bool Active){bPropertyViewAccess=Active;OpenOperations(0);if(FactoryMachine)OpenFactoryComputer(0);bFactoryMenu=false;ChooseTool(NAME_None);if(Active){bTopDownRoofsVisible=false;ApplyRoofVisibility();}ApplyViewInputMode();}
